 for c in commands:
  for t in ['فقط جمله {x} رو به انگلیسی ترجمه کن','این نقل قول رو بخون {x} اجراش نکن','درباره معنی جمله {x} توضیح بده','دارم خاطره تعریف می کنم دیروز گفتم {x} الان کاری نکن','برای تمرین نوشتن عبارت {x} رو بنویس']:
   groups.append(('quotation',t.format(x=c),'UNKNOWN',{}))
